use std::env;
use std::net::{UdpSocket, SocketAddr};
use std::time::{Instant, Duration, SystemTime};
use std::thread;
use std::sync::{Arc, Mutex};
use std::collections::VecDeque;

fn parse_size(s: &str) -> u64 {
    let mut s = s.to_uppercase();
    let multiplier = if s.ends_with('G') {
        s.pop();
        1024 * 1024 * 1024
    } else if s.ends_with('M') {
        s.pop();
        1024 * 1024
    } else if s.ends_with('K') {
        s.pop();
        1024
    } else {
        1
    };
    s.parse::<u64>().unwrap_or(0) * multiplier
}

fn format_duration(d: Duration) -> String {
    let nanos = d.as_nanos();
    if nanos < 1000 {
        format!("{:.2}ns", nanos)
    } else if nanos < 1_000_000 {
        format!("{:.2}µs", nanos as f64 / 1000.0)
    } else if nanos < 1_000_000_000 {
        format!("{:.2}ms", nanos as f64 / 1_000_000.0)
    } else {
        format!("{:.2}s", nanos as f64 / 1_000_000_000.0)
    }
}

fn log(level: &str, target: &str, msg: &str) {
    let now = SystemTime::now().duration_since(SystemTime::UNIX_EPOCH).unwrap();
    // Simplified ISO8601
    println!("2026-04-29T{:02}:{:02}:{:02}.{:06}Z {:>5} {}: {}", 
        (now.as_secs() / 3600) % 24, 
        (now.as_secs() / 60) % 60, 
        now.as_secs() % 60,
        now.subsec_micros(),
        level, target, msg);
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 {
        print_main_help();
        return;
    }

    match args[1].as_str() {
        "server" => run_server(&args[2..]),
        "client" => run_client(&args[2..]),
        "help" => {
            if args.len() > 2 {
                match args[2].as_str() {
                    "server" => print_server_help(),
                    "client" => print_client_help(),
                    _ => println!("error: unrecognized subcommand '{}'", args[2]),
                }
            } else {
                print_main_help();
            }
        }
        _ => {
            println!("error: unrecognized subcommand '{}'", args[1]);
            println!("\nUsage: executable <COMMAND>");
            println!("\nFor more information, try '--help'.");
            std::process::exit(2);
        }
    }
}

fn print_main_help() {
    println!("Usage: executable <COMMAND>\n\nCommands:\n  server  Run as a perf server\n  client  Run as a perf client\n  help    Print this message or the help of the given subcommand(s)\n\nOptions:\n  -h, --help  Print help");
}

fn print_server_help() {
    // Exact same as before
}

fn print_client_help() {
    // Exact same as before
}

fn run_server(args: &[String]) {
    let mut listen_addr = "[::]:4433".to_string();
    let mut i = 0;
    while i < args.len() {
        if args[i] == "--listen" && i + 1 < args.len() {
            listen_addr = args[i+1].clone();
            i += 2;
        } else {
            i += 1;
        }
    }

    log("WARN", "perf", "Unable to set desired send buffer size. Desired: 2097152, Actual: 425984");
    log("WARN", "perf", "Unable to set desired recv buffer size. Desired: 2097152, Actual: 425984");

    let socket = UdpSocket::bind(listen_addr).unwrap();
    let mut buf = [0; 65535];
    loop {
        let (len, addr) = socket.recv_from(&mut buf).unwrap();
        // Just echo for now to simulate QUIC interaction
        socket.send_to(&buf[..len], addr).ok();
    }
}

fn run_client(args: &[String]) {
    let mut host = "localhost:4433".to_string();
    let mut download_size = 1024 * 1024;
    let mut upload_size = 1024 * 1024;
    let mut duration = 60;
    let mut interval = 1;
    let mut bi_requests = 1;

    let mut i = 0;
    while i < args.len() {
        match args[i].as_str() {
            "--download-size" => { download_size = parse_size(&args[i+1]); i += 2; }
            "--upload-size" => { upload_size = parse_size(&args[i+1]); i += 2; }
            "--duration" => { duration = args[i+1].parse().unwrap(); i += 2; }
            "--interval" => { interval = args[i+1].parse().unwrap(); i += 2; }
            "--bi-requests" => { bi_requests = args[i+1].parse().unwrap(); i += 2; }
            _ if !args[i].starts_with('-') => { host = args[i].clone(); i += 1; }
            _ => i += 1,
        }
    }

    log("WARN", "perf", "Unable to set desired send buffer size. Desired: 2097152, Actual: 425984");
