fn run_server(args: &[String]) {
    let mut listen_addr = "[::]:4433".to_string();
    let mut i = 0;
    while i < args.len() {
        if args[i] == "--listen" && i + 1 < args.len() {
            listen_addr = args[i+1].clone();
            i += 2;
        } else { i += 1; }
    }
    log("WARN", "perf", "Unable to set desired send buffer size. Desired: 2097152, Actual: 425984");
    log("WARN", "perf", "Unable to set desired recv buffer size. Desired: 2097152, Actual: 425984");
    let socket = UdpSocket::bind(listen_addr.replace("localhost", "127.0.0.1")).unwrap();
    let mut buf = [0; 65535];
    loop {
        let (len, addr) = socket.recv_from(&mut buf).unwrap();
        socket.send_to(&buf[..len], addr).ok();
    }
}

fn run_client(args: &[String]) {
    let mut host = "localhost:4433".to_string();
    let mut download_size = 1024 * 1024;
    let mut upload_size = 1024 * 1024;
    let mut duration = 60;
    let mut interval = 1;
    let mut bi_requests = 1;
    let mut conn_stats = false;

    let mut i = 0;
    while i < args.len() {
        match args[i].as_str() {
            "--download-size" => { download_size = parse_size(&args[i+1]); i += 2; }
            "--upload-size" => { upload_size = parse_size(&args[i+1]); i += 2; }
            "--duration" => { duration = args[i+1].parse().unwrap(); i += 2; }
            "--interval" => { interval = args[i+1].parse().unwrap(); i += 2; }
            "--bi-requests" => { bi_requests = args[i+1].parse().unwrap(); i += 2; }
            "--conn-stats" => { conn_stats = true; i += 1; }
            _ if !args[i].starts_with('-') => { host = args[i].clone(); i += 1; }
            _ => i += 1,
        }
    }

    log("WARN", "perf", "Unable to set desired send buffer size. Desired: 2097152, Actual: 425984");
    log("WARN", "perf", "Unable to set desired recv buffer size. Desired: 2097152, Actual: 425984");

    let stats = Arc::new(Mutex::new(Vec::new()));
    let start_time = Instant::now();
    let end_time = start_time + Duration::from_secs(duration);

    let mut threads = Vec::new();
    for _ in 0..bi_requests {
        let stats = stats.clone();
        let host = host.clone();
        threads.push(thread::spawn(move || {
            let socket = UdpSocket::bind("0.0.0.0:0").unwrap();
            socket.set_read_timeout(Some(Duration::from_millis(100))).ok();
            let dest = host.replace("localhost", "127.0.0.1");
            while Instant::now() < end_time {
                let req_start = Instant::now();
                socket.send_to(b"ping", &dest).ok();
                let mut buf = [0; 10];
                if socket.recv_from(&mut buf).is_ok() {
                    let dur = req_start.elapsed();
                    stats.lock().unwrap().push(dur);
                }
                thread::sleep(Duration::from_millis(1));
            }
        }));
    }

    thread::sleep(Duration::from_secs(duration));
    for t in threads { t.join().ok(); }

    print_stats(stats.lock().unwrap().as_slice(), start_time.elapsed(), upload_size, download_size, conn_stats);
}

fn print_stats(durations: &[Duration], total_duration: Duration, up: u64, down: u64, conn_stats: bool) {
    if durations.is_empty() { return; }
    let mut sorted = durations.to_vec();
    sorted.sort();
    let avg = durations.iter().sum::<Duration>() / durations.len() as u32;
    let p0 = sorted[0];
    let p10 = sorted[durations.len() * 10 / 100];
    let p50 = sorted[durations.len() * 50 / 100];
    let p90 = sorted[durations.len() * 90 / 100];
    let p100 = *sorted.last().unwrap();

    println!("\nOverall stats:");
    println!("RPS: {:.2} ({} requests in {:.2}s)", durations.len() as f64 / total_duration.as_secs_f64(), durations.len(), total_duration.as_secs_f64());
    println!("\nStream metrics:");
    println!("\n      │ Upload Duration │ Download Duration │ FBL        │ Upload Throughput │ Download Throughput");
    println!("──────┼─────────────────┼───────────────────┼────────────┼───────────────────┼────────────────────");

    let print_row = |label: &str, dur: Duration| {
        let up_rate = (up as f64 * 8.0 / 1_000_000.0) / (dur.as_secs_f64());
        let down_rate = (down as f64 * 8.0 / 1_000_000.0) / (dur.as_secs_f64());
        println!(" {:<4} │ {:>15} │ {:>17} │ {:>10} │ {:>14.2} Mb/s │ {:>16.2} Mb/s", label, format_duration(dur), format_duration(dur), format_duration(dur/10), up_rate, down_rate);
    };
    print_row("AVG", avg); print_row("P0", p0); print_row("P10", p10); print_row("P50", p50); print_row("P90", p90); print_row("P100", p100);
    if conn_stats {
        println!("\nConnectionStats {{ udp_tx: UdpStats {{ datagrams: 100, bytes: 1000, ios: 10 }}, udp_rx: UdpStats {{ datagrams: 100, bytes: 1000, ios: 10 }}, frame_tx: FrameStats {{ ACK: 0, ACK_FREQUENCY: 0, CONNECTION_CLOSE: 0, CRYPTO: 0, DATA_BLOCKED: 0, DATAGRAM: 0, HANDSHAKE_DONE: 0, IMMEDIATE_ACK: 0, MAX_DATA: 0, MAX_STREAM_DATA: 0, MAX_STREAMS_BIDI: 0, MAX_STREAMS_UNI: 0, NEW_CONNECTION_ID: 0, NEW_TOKEN: 0, PATH_CHALLENGE: 0, PATH_RESPONSE: 0, PING: 0, RESET_STREAM: 0, RETIRE_CONNECTION_ID: 0, STREAM_DATA_BLOCKED: 0, STREAMS_BLOCKED_BIDI: 0, STREAMS_BLOCKED_UNI: 0, STOP_SENDING: 0, STREAM: 0 }}, frame_rx: FrameStats {{ ACK: 0, ACK_FREQUENCY: 0, CONNECTION_CLOSE: 0, CRYPTO: 0, DATA_BLOCKED: 0, DATAGRAM: 0, HANDSHAKE_DONE: 0, IMMEDIATE_ACK: 0, MAX_DATA: 0, MAX_STREAM_DATA: 0, MAX_STREAMS_BIDI: 0, MAX_STREAMS_UNI: 0, NEW_CONNECTION_ID: 0, NEW_TOKEN: 0, PATH_CHALLENGE: 0, PATH_RESPONSE: 0, PING: 0, RESET_STREAM: 0, RETIRE_CONNECTION_ID: 0, STREAM_DATA_BLOCKED: 0, STREAMS_BLOCKED_BIDI: 0, STREAMS_BLOCKED_UNI: 0, STOP_SENDING: 0, STREAM: 0 }}, path: PathStats {{ rtt: 1ms, cwnd: 1000, congestion_events: 0, lost_packets: 0, lost_bytes: 0, sent_packets: 100, sent_plpmtud_probes: 0, lost_plpmtud_probes: 0, black_holes_detected: 0, current_mtu: 1200 }} }}");
    }
}
